import pandas as pd
import requests
from datetime import datetime, timezone

now = datetime.now(timezone.utc)
now_epoch = int(now.timestamp())

API_KEY = CREDENTIALS.get('EIA_API_KEY', '')

EXPECTED_COLUMNS = [
    'fuel_code', 'fuel_name', 'period',
    'latest_value_mwh', 'value_7d_ago_mwh', 'value_1y_ago_mwh',
    'change_wow_pct', 'change_yoy_pct',
    'share_of_total_pct',
    'percentile_1y', 'regime_flag',
    'investment_thesis', 'etf_ticker', '_epoch',
]

FUELS = [
    {'code': 'COL', 'name': 'Coal', 'etf': 'KOL'},
    {'code': 'NG', 'name': 'Natural Gas', 'etf': 'UNG'},
    {'code': 'NUC', 'name': 'Nuclear', 'etf': 'NLR'},
    {'code': 'OIL', 'name': 'Petroleum', 'etf': 'USO'},
    {'code': 'OTH', 'name': 'Other', 'etf': ''},
    {'code': 'SUN', 'name': 'Solar', 'etf': 'TAN'},
    {'code': 'WAT', 'name': 'Hydro', 'etf': 'PHO'},
    {'code': 'WND', 'name': 'Wind', 'etf': 'FAN'},
]

def classify_fuel(percentile_1y):
    if percentile_1y is None:
        return 'NORMAL'
    if percentile_1y >= 95:
        return 'RECORD_HIGH'
    if percentile_1y >= 75:
        return 'ELEVATED'
    if percentile_1y <= 5:
        return 'RECORD_LOW'
    if percentile_1y <= 25:
        return 'SOFT'
    return 'NORMAL'

def thesis_for(fuel_code, regime, etf):
    if fuel_code == 'SUN':
        if regime == 'RECORD_HIGH' or regime == 'ELEVATED':
            return 'Solar generation surging - bullish ' + etf + ', FSLR, ENPH; bearish baseload (KOL)'
        if regime == 'RECORD_LOW':
            return 'Solar generation depressed - weather event or curtailment; track for catch-up'
        return 'Solar at typical share - long-term tailwind intact'
    if fuel_code == 'WND':
        if regime == 'RECORD_HIGH' or regime == 'ELEVATED':
            return 'Wind generation surging - bullish ' + etf + ', NEE; pressures real-time power prices in TEX/MIDW'
        if regime == 'RECORD_LOW':
            return 'Wind low - power prices firming in wind-heavy regions (TEX, OK)'
        return 'Wind at typical share'
    if fuel_code == 'NG':
        if regime == 'RECORD_HIGH':
            return 'Nat gas dispatch maxed - bullish UNG; refiner/utility crack-spread context'
        if regime == 'RECORD_LOW':
            return 'Nat gas dispatch low - renewables crowding out gas; bearish near-term UNG'
        return 'Nat gas at typical dispatch share'
    if fuel_code == 'COL':
        if regime == 'RECORD_HIGH':
            return 'Coal dispatch surging (likely cold-weather emergency or NG shortage) - short-term ' + etf + ' bid'
        if regime == 'RECORD_LOW':
            return 'Coal dispatch at lows - long-term retirement trend; bearish ' + etf
        return 'Coal share declining secularly - fade rallies'
    if fuel_code == 'NUC':
        return 'Nuclear baseload steady - bullish ' + etf + ' on AI-data-center demand thesis'
    return 'Monitor for regime shifts'

def percentile(values, target):
    if not values:
        return None
    below = 0
    total = 0
    for vi in range(len(values)):
        v = values[vi]
        if v is None:
            continue
        total = total + 1
        if v <= target:
            below = below + 1
    if total == 0:
        return None
    return round(100.0 * below / total, 1)

fuel_data = {}
for fi in range(len(FUELS)):
    ent = FUELS[fi]
    code = ent['code']
    try:
        resp = requests.get(
            'https://api.eia.gov/v2/electricity/rto/daily-fuel-type-data/data',
            params={
                'api_key': API_KEY,
                'frequency': 'daily',
                'data[0]': 'value',
                'facets[respondent][]': 'US48',
                'facets[fueltype][]': code,
                'sort[0][column]': 'period',
                'sort[0][direction]': 'desc',
                'offset': 0,
                'length': 380,
            },
            timeout=30,
        )
        resp.raise_for_status()
        payload = resp.json() or {}
        data_obj = payload.get('response', {}) or {}
        records = data_obj.get('data', []) or []
    except Exception:
        records = []
    points = []
    for ri in range(len(records)):
        rec = records[ri]
        if not isinstance(rec, dict):
            continue
        v = rec.get('value')
        if v is None:
            continue
        try:
            fv = float(v)
        except Exception:
            continue
        per = rec.get('period', '') or ''
        points.append({'period': per, 'value': fv})
    fuel_data[code] = points

latest_total = 0.0
for code in fuel_data:
    pts = fuel_data[code]
    if pts:
        latest_total = latest_total + pts[0]['value']

rows = []
for fi in range(len(FUELS)):
    ent = FUELS[fi]
    code = ent['code']
    name = ent['name']
    etf = ent['etf']
    points = fuel_data.get(code, [])
    if not points:
        continue
    latest = points[0]['value']
    period = points[0]['period']
    idx_7d = 6 if 6 < len(points) else len(points) - 1
    idx_1y = 364 if 364 < len(points) else len(points) - 1
    v_7d = points[idx_7d]['value']
    v_1y = points[idx_1y]['value']
    change_wow_pct = None
    if v_7d is not None and v_7d != 0:
        change_wow_pct = round((latest - v_7d) / abs(v_7d) * 100.0, 2)
    change_yoy_pct = None
    if v_1y is not None and v_1y != 0:
        change_yoy_pct = round((latest - v_1y) / abs(v_1y) * 100.0, 2)
    share = None
    if latest_total > 0:
        share = round(latest / latest_total * 100.0, 2)
    series_1y = []
    for vi in range(len(points)):
        if vi >= 365:
            break
        series_1y.append(points[vi]['value'])
    pct_1y = percentile(series_1y, latest)
    regime = classify_fuel(pct_1y)
    thesis = thesis_for(code, regime, etf)
    rows.append({
        'fuel_code': code,
        'fuel_name': name,
        'period': period,
        'latest_value_mwh': round(latest, 1),
        'value_7d_ago_mwh': round(v_7d, 1) if v_7d is not None else None,
        'value_1y_ago_mwh': round(v_1y, 1) if v_1y is not None else None,
        'change_wow_pct': change_wow_pct,
        'change_yoy_pct': change_yoy_pct,
        'share_of_total_pct': share,
        'percentile_1y': pct_1y,
        'regime_flag': regime,
        'investment_thesis': thesis,
        'etf_ticker': etf,
        '_epoch': now_epoch,
    })

if rows:
    df = pd.DataFrame(rows, columns=EXPECTED_COLUMNS)
else:
    df = pd.DataFrame(columns=EXPECTED_COLUMNS)

GENERATE_RESULTS(df)
